// Lists of words, counted, and made arrays: loading makes a quoted
// vector so (C80), and the primitives (vwords.kfx).
pub fn list_count(mut xs: i64, mut n: i64) -> i64 {
    loop {
        if i64_eq(xs, w_nil()) {
            return n;
        } else {
            (xs, n) = (pair_cdr(xs), i64_plus(n, 1i64));
            continue;
        }
    }
}

/// How many elements the list at `fast` has (`n` so far), `slow` half
/// as far along: -1 if it ends in no `()` or meets itself, a cycle.
pub fn proper_count(mut slow: i64, mut fast: i64, mut n: i64) -> i64 {
    loop {
        if i64_eq(fast, w_nil()) {
            return n;
        } else if not(is_obj_p(fast, ob_pair())) {
            return -1i64;
        } else if i64_eq(pair_cdr(fast), w_nil()) {
            return i64_plus(n, 1i64);
        } else if not(is_obj_p(pair_cdr(fast), ob_pair())) {
            return -1i64;
        } else if (i64_gt(n, 0i64) && i64_eq(pair_cdr(slow), pair_cdr(pair_cdr(fast)))) {
            return -1i64;
        } else {
            (slow, fast, n) = (pair_cdr(slow), pair_cdr(pair_cdr(fast)), i64_plus(n, 2i64));
            continue;
        }
    }
}

pub fn from_list_x(mut p: i64, mut i: i64, mut xs: i64) -> () {
    loop {
        if i64_eq(xs, w_nil()) {
            return ();
        } else {
            obj_set_x(p, i, pair_car(xs));
            (i, xs) = (i64_plus(i, 1i64), pair_cdr(xs));
            continue;
        }
    }
}

pub fn list_array_x(kind: i64, xs: i64) -> i64 {
    let p = alloc_x(kind, list_count(xs, 0i64));
    from_list_x(p, 0i64, xs);
    p
}

